package com.ebuddy.j2me;
import javax.microedition.lcdui.*; import java.util.Vector;
public final class ContactList extends List implements CommandListener { final EbuddyMidlet app; final Command refresh=new Command("Refresh",Command.SCREEN,1); final Command logout=new Command("Logout",Command.EXIT,9); Vector data=new Vector(); public ContactList(EbuddyMidlet a){super("Contacts",List.IMPLICIT);app=a;addCommand(refresh);addCommand(logout);setCommandListener(this);} void load(){app.net.request(NetworkWorker.CONTACTS,"/api/contacts?limit=20",null);} void setItems(Vector v){data=v;deleteAll();for(int i=0;i<v.size();i++)append(((Contact)v.elementAt(i)).toString(),null);if(v.size()==0)append("No contacts",null);app.poll();} Contact selected(){int i=getSelectedIndex();return i>=0&&i<data.size()?(Contact)data.elementAt(i):null;} public void commandAction(Command c,Displayable d){if(c==refresh)load();else if(c==logout)app.logout();else if(c==List.SELECT_COMMAND&&selected()!=null)app.openChat(selected());}}
